// every marker kind from the same payload:
// { redHeads: { <headSha>: <highest recorded N> },
//   emptyLaps: { <headSha>: <highest recorded N> }.
// Probe failure fails OPEN (empty state → arm): a broken comment read
// must not strand a red head that these caps exist to un-stall — the
// next red re-reads and re-evaluates.
function failMarkerState(repoInfo, prNumber) {
    var out = { redHeads: {}, emptyLaps: {}, zombies: {}, placeholders: null,
                placeholderParked: false, reworkWithheld: {} };
    var bodies = [];
    try {
        var raw = github_get_pr_comments({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            pullRequestId: prNumber
        });
        var obj = typeof raw === 'string' ? JSON.parse(raw) : (raw || []);
        var list = Array.isArray(obj) ? obj : (obj.comments || obj.items || []);
        list.forEach(function (c) {
            var body = String((c && c.body) || '');
            bodies.push(body);
            var m;
            RED_HEAD_MARKER_RE.lastIndex = 0;
            while ((m = RED_HEAD_MARKER_RE.exec(body)) !== null) {
                var rn = parseInt(m[2], 10) || 0;
                if (!out.redHeads[m[1]] || rn > out.redHeads[m[1]]) out.redHeads[m[1]] = rn;
            }
            EMPTY_LAP_MARKER_RE.lastIndex = 0;
            while ((m = EMPTY_LAP_MARKER_RE.exec(body)) !== null) {
                var ln = parseInt(m[1], 10) || 0;
                if (!out.emptyLaps[m[3]] || ln > out.emptyLaps[m[3]]) out.emptyLaps[m[3]] = ln;
            }
        });
    } catch (eMarks) {
        console.warn('  ⚠️  fail-marker state read failed: ' + (eMarks.message || eMarks));
    }
    // gh-821 zombie re-dispatch bookkeeping (js/common/validationLiveness.js):
    // parsed from the SAME single comment fetch — per-head re-dispatch counts
    // (crash-loop cap) and the newest marker's timestamp (1/head/hour bound).
    // A read failure above leaves {} — the zombie branch then treats the head
    // as never-re-dispatched (one bounded extra dispatch worst case).
    try {
        out.zombies = validationLivenessModule.zombieMarks(bodies);
    } catch (eZomb) {
        console.warn('  ⚠️  zombie-marker parse failed: ' + (eZomb.message || eZomb));
    }
    // gh-852 placeholder-reset bookkeeping (js/common/checkRunZombies.js):
    // same single comment fetch — per-PR windowed reset count (AC2 storm
    // cap; per PR, NOT per head: every reset mints a NEW head, so head-
    // keyed counting would never reach a cap) + whether the cap-park note
    // was already posted (once-per-cap-hit pacing).
    try {
        out.placeholders = checkRunZombiesModule.placeholderMarks(
            bodies, Date.now(), checkRunZombiesModule.placeholderWindowMsOf(RUN_JOB_PARAMS));
        out.placeholderParked = bodies.some(function (b) {
            return String(b == null ? '' : b).indexOf(PLACEHOLDER_PARK_MARKER) !== -1;
        });
    } catch (ePh) {
        console.warn('  ⚠️  placeholder-marker parse failed: ' + (ePh.message || ePh));
        out.placeholders = { count: 0, lastAtMs: null };
    }
    // gh-917 red-gate rework bookkeeping: the SAME single comment fetch —
    // which heads already carry the 🛑 withheld-at-cap escalation (the
    // once-per-head dedup for the redHeadGated arm_rework path; without it
    // a stuck red head would re-post the escalation every tick). A read
    // failure above leaves {} — the withhold branch then re-posts (fail
    // toward visibility, same contract as conflict_rework's marker scan).
    try {
        out.reworkWithheld = {};
        var wmr;
        REWORK_WITHHELD_MARKER_RE.lastIndex = 0;
        bodies.forEach(function (b) {
            REWORK_WITHHELD_MARKER_RE.lastIndex = 0;
            while ((wmr = REWORK_WITHHELD_MARKER_RE.exec(String(b == null ? '' : b))) !== null) {
                out.reworkWithheld[wmr[1]] = true;
            }
        });
    } catch (eWmr) {
        console.warn('  ⚠️  withheld-arm marker parse failed: ' + (eWmr.message || eWmr));
        out.reworkWithheld = {};
    }
    return out;
}

