+            type: 'pr',
+            checks: ['red'],
+            notLabels: ['ai_validating', 'validation_failed', 'agent:rework', 'chore:pin'],
+            prMachineAuthor: true,
+            notMergeState: ['BEHIND', 'DIRTY'],
+            draft: false
+        },
+        localAction: 'arm_rework',
+        redHeadGated: true,
+        limit: 1,
+        id: 'rework-on-red-gate-unlatched'
