+        return it;
+    }
+
+    function config(owner, repo) {
+        return { fileMap: { '../.dmtools/config.js':
+            'module.exports = { repository: { owner: "' + owner + '", repo: "' + repo + '" } };' } };
+    }
+
+    function markerComment(body) { return { body: body }; }
+
+    var HEAD = 'a413a413a413a413a413a413a413a413a413a413';
+
