var REWORK_WITHHELD_MARKER_RE = /\uD83D\uDED1 rework arm withheld on head ([0-9a-f]{7,40})/g;

function redHeadCapOf(jobParams) {
    // Default 3 reds on the same head (owner directive 2026-10-04);
