    // would load the actual .dmtools/config.js regardless of what fileMap says.
    var freshConfigLoader = loadModule(
        'js/configLoader.js',
        makeRequire({ './config.js': configModule, './common/scm.js': mockScmModule }),
        { file_read: fileReadMock }
    );


