                ') for (pr-' + prNumber + ', ' + head.substring(0, 7) + ')');
        }
        return { latched: false, head: head };
    }
    console.log('  ⏭️  ' + key + ' rework already in flight for (pr-' + prNumber +
        ', ' + head.substring(0, 7) + ')');
